export class Fold{constructor(){this.folds=document.querySelectorAll("[data-fold]"),this.folds.length&&this.init()}init(){this.folds.forEach(t=>{const e=t.parentElement.querySelector("[data-fold-btn]");if(t.scrollHeight<=t.clientHeight+30)return t.classList.add("is-open"),void(e&&e.remove());e&&e.addEventListener("click",()=>{const s=t.classList.toggle("is-open");e.textContent=s?"Свернуть":"Читать полностью",e.setAttribute("aria-expanded",String(s))})})}}